CREATE TABLE IF NOT EXISTS coupons (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, type TEXT NOT NULL DEFAULT 'percent', value INTEGER NOT NULL DEFAULT 0, min_order INTEGER NOT NULL DEFAULT 0, max_discount INTEGER, starts_at TEXT, ends_at TEXT, usage_limit INTEGER, once_per_customer INTEGER NOT NULL DEFAULT 0, auto_apply INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, note TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
ALTER TABLE orders ADD COLUMN discount_paise INTEGER NOT NULL DEFAULT 0;
ALTER TABLE orders ADD COLUMN coupon_code TEXT;
